// ============================================================
// NODE 1 — CALCULADORA DE SCORE (regras comerciais revisadas)
// Tipo: Code (JavaScript) no n8n
// Input: $json.body.lead
// Lógica: nenhum lead com intenção fica sem produto
// ============================================================

const lead = $json.body.lead;

// ── NORMALIZAÇÃO ────────────────────────────────────────────

function normalizeEnglish(val = "") {
  const v = val.toLowerCase();
  if (v.includes("fluente") || v.includes("nativo") || v.includes("native"))                        return "Fluente";
  if (v.includes("avançado") || v.includes("avancado") || v.includes("advanced"))                   return "Avançado";
  if (v.includes("intermediário") || v.includes("intermediario") || v.includes("intermediate"))     return "Intermediário";
  return "Básico";
}

function normalizeExperience(val = "") {
  const v = val.toLowerCase().replace(/\s/g, "");
  if (v.includes("+10") || v.includes("10+") || v.includes("maisde10") || v.includes("acimade10")) return "+10 anos";
  if (v.includes("5-10") || v.includes("5a10") || v.includes("5e10"))                              return "5-10 anos";
  if (v.includes("2-5")  || v.includes("2a5")  || v.includes("2e5"))                               return "2-5 anos";
  return "Menos de 2 anos";
}

function normalizeArea(val = "") {
  const v = val.toLowerCase();
  if (v.includes("sap") || v.includes("erp"))                                                                        return "SAP/ERP";
  if (v.includes("tecnologia") || v.includes(" ti") || v.includes("/ti") || v.includes("/it") || v.includes(" it")) return "Tecnologia/IT";
  if (v.includes("gestão") || v.includes("gestao") || v.includes("business") || v.includes("negócio"))              return "Gestão/Business";
  if (v.includes("engenharia") || v.includes("engineering"))                                                         return "Engenharia";
  return "Outros";
}

function normalizeObjective(val = "") {
  const v = val.toLowerCase();
  if (v.includes("green card") || v.includes("imigrar") || v.includes("imigração")) return "Imigrar/Green Card trabalhando na minha área";
  if (v.includes("remoto") || v.includes("dólar") || v.includes("dolar"))           return "Emprego remoto em dólar";
  if (v.includes("estudar") || v.includes("estudo") || v.includes("faculdade"))     return "Estudar nos EUA como porta de entrada";
  return "Ainda não tenho clareza, quero entender minhas opções";
}

function normalizeVisa(val = "") {
  const v = val.toLowerCase();
  if (v.includes("green card") || (v.includes("trabalho") && v.includes("aprovado"))) return "Já tenho visto de trabalho ou Green Card aprovado";
  if (v.includes("andamento") || v.includes("em processo") || v.includes("em curso")) return "Processo de visto/imigração em andamento";
  if (v.includes("turista") || v.includes("tourist") || v.includes("b1") || v.includes("b2")) return "Tenho/tive apenas visto de turista";
  return "Ainda não iniciei nada";
}

function normalizeTimeline(val = "") {
  const v = val.toLowerCase();
  if (v.includes("movimento") || (v.includes("3 meses") && v.includes("próximo"))) return "Já estou em movimento / próximos 3 meses";
  if (v.includes("3") && v.includes("6"))                                           return "Entre 3 e 6 meses";
  if (v.includes("6") && v.includes("12"))                                          return "Entre 6 e 12 meses";
  return "Ainda não tenho prazo definido";
}

function normalizeFamilyStatus(val = "") {
  const v = val.toLowerCase();
  if (v.includes("filho"))                                                                                  return "Com família e filhos";
  if (v.includes("cônjuge") || v.includes("conjuge") || v.includes("companheiro") || v.includes("casado")) return "Com cônjuge/companheiro(a)";
  if (v.includes("sozinho") || v.includes("sozinha") || v.includes("solteiro"))                            return "Sozinho(a)";
  return "Ainda não pensei sobre isso";
}

function normalizeIncome(val = "") {
  const v = val.toLowerCase().replace(/\s/g, "");
  if (v.includes("prefiro") || v.includes("nãoresponder"))                               return "Prefiro não responder";
  if (v.includes("acimade20") || (v.includes("20") && v.includes("acima")))              return "Acima de R$ 20 mil";
  if (v.includes("10") && v.includes("20"))                                              return "De R$ 10 mil a R$ 20 mil";
  if (v.includes("5") && v.includes("10"))                                               return "De R$ 5 mil a R$ 10 mil";
  if (v.includes("até5mil") || v.includes("ate5mil") || v.includes("5mil") || v.includes("5.000")) return "Até R$ 5 mil";
  return "Prefiro não responder";
}

function normalizeInvestment(val = "") {
  const v = val.toLowerCase().replace(/\s/g, "");
  if (v.includes("nãosei") || v.includes("naose") || v.includes("organizar"))                         return "Ainda não sei/preciso me organizar primeiro";
  if (v.includes("acimade5") || (v.includes("5mil") && v.includes("acima")))                          return "Acima de R$ 5 mil";
  if ((v.includes("3mil") || v.includes("3.000")) && v.includes("5"))                                 return "De R$ 3 mil a R$ 5 mil";
  if ((v.includes("1.500") || v.includes("1500")) && (v.includes("3") || v.includes("3.000")))        return "De R$ 1.500 a R$ 3.000";
  if (v.includes("até1.500") || v.includes("ate1500") || (v.includes("1.500") && v.includes("até"))) return "Até R$ 1.500";
  return "Ainda não sei/preciso me organizar primeiro";
}

function normalizeImpediment(val = "") {
  const v = (val || "").toLowerCase();
  if (v.includes("pronto") || v.includes("nenhum"))                                                   return "Nenhum, pois estou pronto(a)";
  if (v.includes("financeiro") || v.includes("dinheiro") || v.includes("custo"))                     return "Financeiro";
  if (v.includes("tempo") || v.includes("rotina") || v.includes("agenda"))                           return "Tempo ou rotina";
  if (v.includes("inglês") || v.includes("ingles") || v.includes("idioma"))                          return "Inglês";
  if (v.includes("medo") || v.includes("decisão") || v.includes("decisao") || v.includes("errada")) return "Medo de tomar uma decisão errada";
  if (v.includes("família") || v.includes("familia") || v.includes("cônjuge") || v.includes("apoio")) return "Falta de apoio do cônjuge ou família";
  return "Outro";
}

function normalizeWorksInternational(val = "") {
  const v = (val || "").toLowerCase().trim();
  return (v === "sim" || v === "yes" || v === "s" || v === "true") ? "Sim" : "Não";
}

// ── DADOS NORMALIZADOS ──────────────────────────────────────

const input = {
  name:                   lead.fullName    || "",
  email:                  lead.email       || "",
  phone:                  (lead.ddd || "") + (lead.whatsapp || ""),
  area:                   normalizeArea(lead.area),
  raw_area:               lead.area        || "",
  atuacao:                lead.currentRole || "",
  current_role:           lead.currentRole || "",
  trabalha_internacional: normalizeWorksInternational(lead.worksInternational),
  experiencia:            normalizeExperience(lead.experience),
  english_level:          normalizeEnglish(lead.englishLevel),
  raw_english_level:      lead.englishLevel || "",
  objetivo:               normalizeObjective(lead.goal),
  visa_status:            normalizeVisa(lead.visaStatus),
  timeline:               normalizeTimeline(lead.timeline),
  family_status:          normalizeFamilyStatus(lead.familyStatus),
  income_range:           normalizeIncome(lead.incomeRange),
  investment_range:       normalizeInvestment(lead.investmentRange),
  impediment:             normalizeImpediment(lead.impediment),
  main_concern:           lead.mainConcern || "",
};

// ── SCORE ───────────────────────────────────────────────────

const score_english            = { "Básico": 0, "Intermediário": 12, "Avançado": 20, "Fluente": 25 }[input.english_level] ?? 0;
const score_experience         = { "Menos de 2 anos": 5, "2-5 anos": 12, "5-10 anos": 17, "+10 anos": 20 }[input.experiencia] ?? 0;
const score_international_work = input.trabalha_internacional === "Sim" ? 15 : 5;
const score_timeline           = { "Já estou em movimento / próximos 3 meses": 10, "Entre 3 e 6 meses": 8, "Entre 6 e 12 meses": 5, "Ainda não tenho prazo definido": 2 }[input.timeline] ?? 0;
const score_objective          = { "Imigrar/Green Card trabalhando na minha área": 10, "Emprego remoto em dólar": 8, "Estudar nos EUA como porta de entrada": 6, "Ainda não tenho clareza, quero entender minhas opções": 0 }[input.objetivo] ?? 0;
const score_visa               = { "Já tenho visto de trabalho ou Green Card aprovado": 10, "Processo de visto/imigração em andamento": 7, "Tenho/tive apenas visto de turista": 3, "Ainda não iniciei nada": 0 }[input.visa_status] ?? 0;
const score_readiness          = { "Nenhum, pois estou pronto(a)": 10, "Tempo ou rotina": 6, "Medo de tomar uma decisão errada": 4, "Financeiro": 3, "Inglês": 2, "Falta de apoio do cônjuge ou família": 1, "Outro": 3 }[input.impediment] ?? 3;
const score_area_bonus         = 0;

const readiness_score = Math.min(
  score_english + score_experience + score_international_work +
  score_timeline + score_objective + score_visa + score_readiness + score_area_bonus,
  100
);

// ── FASE ────────────────────────────────────────────────────

let phase;
if      (readiness_score <= 35) phase = { phase_id: 0, phase_name: "BASE INSUFICIENTE",      phase_emoji: "❌", phase_color: "#DC2626", rota_letter: "Pré-R", urgency_level: "BAIXA",   can_apply_jobs: false, estimated_preparation_months: 24 };
else if (readiness_score <= 60) phase = { phase_id: 1, phase_name: "PREPARAÇÃO ESTRUTURADA", phase_emoji: "🟡", phase_color: "#F59E0B", rota_letter: "R-O",   urgency_level: "MÉDIA",   can_apply_jobs: false, estimated_preparation_months: 15 };
else if (readiness_score <= 85) phase = { phase_id: 2, phase_name: "TRAÇÃO ATIVA",           phase_emoji: "🟢", phase_color: "#10B981", rota_letter: "O-T",   urgency_level: "ALTA",    can_apply_jobs: true,  estimated_preparation_months: 9  };
else                            phase = { phase_id: 3, phase_name: "ACELERAÇÃO",             phase_emoji: "🚀", phase_color: "#8B5CF6", rota_letter: "T-A",   urgency_level: "CRÍTICA", can_apply_jobs: true,  estimated_preparation_months: 3  };

// ── BARREIRAS ───────────────────────────────────────────────

const barriers = {
  has_english_barrier:    ["Básico", "Intermediário"].includes(input.english_level),
  has_experience_barrier: ["Menos de 2 anos", "2-5 anos"].includes(input.experiencia),
  has_financial_barrier:  input.income_range === "Até R$ 5 mil" || input.impediment === "Financeiro",
  has_family_barrier:     input.family_status === "Com família e filhos" || input.impediment === "Falta de apoio do cônjuge ou família",
  has_visa_barrier:       input.visa_status === "Ainda não iniciei nada",
  has_time_barrier:       input.impediment === "Tempo ou rotina",
  has_clarity_barrier:    input.objetivo === "Ainda não tenho clareza, quero entender minhas opções",
};

// ── CLASSIFICAÇÃO COMERCIAL ─────────────────────────────────
//
// FILOSOFIA: nenhum lead com intenção fica sem produto.
// A pergunta não é "você qualifica?" mas "onde você entra agora?"
//
// FREE  → incapacidade financeira confirmada por dados concretos (não por declaração de medo)
// LOW   → piso de quem tem intenção mas não encaixa em MED/HIGH
// MED   → budget disponível + inglês mínimo (impedimento não é veto)
// HIGH  → score alto + renda alta + budget alto + urgência real
//
// Ordem de avaliação: HIGH → MED → FREE → LOW (LOW é sempre o fallback)

// HIGH: critério rigoroso — precisa de tudo alinhado
const isHighTicket =
  readiness_score >= 65 &&
  ["De R$ 3 mil a R$ 5 mil", "Acima de R$ 5 mil"].includes(input.investment_range) &&
  ["De R$ 10 mil a R$ 20 mil", "Acima de R$ 20 mil"].includes(input.income_range) &&
  input.english_level !== "Básico" &&
  ["Já estou em movimento / próximos 3 meses", "Entre 3 e 6 meses", "Entre 6 e 12 meses"].includes(input.timeline);

// MED: flexível — budget disponível + inglês mínimo são suficientes
// impediment e income_range não bloqueiam mais
const isMedTicket =
  !isHighTicket &&
  readiness_score >= 40 &&
  ["De R$ 1.500 a R$ 3.000", "De R$ 3 mil a R$ 5 mil", "Acima de R$ 5 mil"].includes(input.investment_range) &&
  ["Intermediário", "Avançado", "Fluente"].includes(input.english_level);

// FREE: apenas quando incapacidade financeira é confirmada por dados concretos
// impediment === "Financeiro" sozinho NÃO é suficiente
const isFree =
  readiness_score < 25 ||
  (
    input.income_range === "Até R$ 5 mil" &&
    ["Até R$ 1.500", "Ainda não sei/preciso me organizar primeiro"].includes(input.investment_range)
  );

// LOW: fallback — qualquer lead com intenção que não se encaixa nos outros
// inclui: inglês básico, pouca experiência, sem prazo, investment baixo
const isLowTicket = !isHighTicket && !isMedTicket && !isFree;

// ── PRODUTO & FIT SCORE ─────────────────────────────────────

let product, fit_score, estimated_ltv;

if (isHighTicket) {
  product = {
    recommended_product_tier:  "HIGH_TICKET",
    recommended_product_name:  "Mentoria Individual com Daniel Kiel",
    recommended_product_price: "12x R$ 997 ou R$ 10.000 à vista",
    recommended_product_url:   "https://mentoria.euanapratica.com/",
  };
  fit_score     = Math.min(85 + Math.round((readiness_score - 65) / 2), 100);
  estimated_ltv = 10000;

} else if (isMedTicket) {
  product = {
    recommended_product_tier:  "MED_TICKET",
    recommended_product_name:  "Mentoria em Grupo ROTA EUA™",
    recommended_product_price: "12x R$ 247 ou R$ 2.497 à vista",
    recommended_product_url:   "https://imersao.euanapratica.com",
  };
  // fit_score penalizado se impedimento financeiro — ainda é MED, mas vendedor sabe que precisa trabalhar objeção
  const impediment_penalty = input.impediment === "Financeiro" ? 8 : 0;
  fit_score     = Math.min(70 + Math.round((readiness_score - 40) / 2.5) - impediment_penalty, 85);
  estimated_ltv = 2500;

} else if (isFree) {
  product = {
    recommended_product_tier:  "FREE",
    recommended_product_name:  "Recursos Gratuitos EUA na Prática",
    recommended_product_price: "Gratuito",
    recommended_product_url:   "https://hub.euanapratica.com/",
  };
  fit_score     = Math.min(30 + Math.round(readiness_score / 2), 50);
  estimated_ltv = 0;

} else {
  // LOW_TICKET — fallback universal
  product = {
    recommended_product_tier:  "LOW_TICKET",
    recommended_product_name:  "Curso ROTA Internacional",
    recommended_product_price: "12x R$ 67 ou R$ 697 à vista",
    recommended_product_url:   "https://rota.euanapratica.com",
  };
  fit_score     = Math.min(50 + Math.round(readiness_score / 5), 70);
  estimated_ltv = 700;
}

const has_budget = product.recommended_product_tier !== "FREE";
const budget_gap =
  isHighTicket ? "Compatível" :
  isMedTicket  ? input.impediment === "Financeiro" ? "Tem budget mas precisa superar objeção financeira" : "Compatível com parcelamento" :
  isFree       ? "Sem orçamento no momento" :
                 "Acessível";

// ── TEMPERATURA & PRIORITY ──────────────────────────────────

const lead_temperature =
  readiness_score >= 80 && has_budget ? "SUPER_QUENTE" :
  readiness_score >= 65 && has_budget ? "QUENTE" :
  readiness_score >= 40               ? "MORNO" :   // baixado de 45 para 40 alinhado com MED
                                        "FRIO";

const urgency_bonus       = phase.urgency_level === "CRÍTICA" ? 10 : phase.urgency_level === "ALTA" ? 5 : 0;
const lead_priority_score = Math.round(
  (readiness_score * 0.4) + (fit_score * 0.3) + (has_budget ? 20 : 0) + urgency_bonus
);

// ── ENRICHMENT ──────────────────────────────────────────────

const enrichment = {
  is_tech_professional: input.area === "Tecnologia/IT",
  is_senior_level:      ["5-10 anos", "+10 anos"].includes(input.experiencia),
  works_remotely:       input.trabalha_internacional === "Sim",
  has_family:           input.family_status === "Com família e filhos",
  is_high_income:       ["De R$ 10 mil a R$ 20 mil", "Acima de R$ 20 mil"].includes(input.income_range),
};

// ── UPSELL PATH ─────────────────────────────────────────────
// Define o caminho natural de evolução deste lead

const upsell_path =
  isHighTicket ? "Manter em HIGH → Alumni/Indicações" :
  isMedTicket  ? "MED → oferta HIGH após 60-90 dias se score evoluir" :
  isFree       ? "FREE → oferta LOW após 30-60 dias quando organizar financeiro" :
                 "LOW → oferta MED após completar módulos iniciais";

// ── DATAS ───────────────────────────────────────────────────

const today     = new Date();
const addDays   = (d, n) => new Date(d.getTime() + n * 86400000).toISOString().split("T")[0];
const addMonths = (d, n) => { const r = new Date(d); r.setMonth(r.getMonth() + n); return r.toISOString().split("T")[0]; };

const milestone = {
  0: { action: "Atingir inglês B2 e ganhar 2+ anos de experiência internacional",   months: 24, recheck: 6 },
  1: { action: "Elevar inglês para C1 e otimizar LinkedIn para o mercado americano", months: 15, recheck: 4 },
  2: { action: "Aplicar para 20+ vagas estratégicas e conseguir 3+ entrevistas",    months: 9,  recheck: 2 },
  3: { action: "Negociar ofertas simultaneamente e iniciar processo de visto",       months: 3,  recheck: 1 },
}[phase.phase_id];

// ── NURTURE SEQUENCE ────────────────────────────────────────
// Sequência específica considerando o produto E as barreiras

let auto_nurture_sequence;
if (isFree && barriers.has_financial_barrier) {
  auto_nurture_sequence = "Free_FinancialBarrier_Nurture";   // novo — nutre para LOW quando organizar $
} else if (isFree) {
  auto_nurture_sequence = "Free_Content_Engagement";
} else if (phase.phase_id === 0 && barriers.has_english_barrier) {
  auto_nurture_sequence = "Fase0_Ingles_Basico";
} else if (phase.phase_id === 0 && barriers.has_experience_barrier) {
  auto_nurture_sequence = "Fase0_Sem_Experiencia";
} else if (isMedTicket && barriers.has_financial_barrier) {
  auto_nurture_sequence = "Fase1_Med_Ticket_FinancialObjection"; // novo — MED com objeção financeira
} else if (isMedTicket) {
  auto_nurture_sequence = "Fase1_Med_Ticket_Nurture";
} else if (isLowTicket && phase.phase_id === 1) {
  auto_nurture_sequence = "Fase1_Low_Ticket_Education";
} else if (phase.phase_id === 2) {
  auto_nurture_sequence = "Fase2_Traction_Active";
} else {
  auto_nurture_sequence = "Fase3_Acceleration_VIP";
}

// ── RETORNO ─────────────────────────────────────────────────

return [{
  json: {
    user_data: {
      name:                   input.name,
      email:                  input.email,
      phone:                  input.phone,
      area:                   input.area,
      raw_area:               input.raw_area,
      atuacao:                input.atuacao,
      current_role:           input.current_role,
      trabalha_internacional: input.trabalha_internacional,
      experiencia:            input.experiencia,
      english_level:          input.english_level,
      raw_english_level:      input.raw_english_level,
      objetivo:               input.objetivo,
      visa_status:            input.visa_status,
      timeline:               input.timeline,
      family_status:          input.family_status,
      income_range:           input.income_range,
      investment_range:       input.investment_range,
      impediment:             input.impediment,
      main_concern:           input.main_concern,
    },

    scoring: {
      readiness_score,
      readiness_percentual: Math.round(readiness_score),
      max_score: 100,
      score_breakdown: {
        score_english,
        score_experience,
        score_international_work,
        score_timeline,
        score_objective,
        score_visa,
        score_readiness,
        score_area_bonus,
      },
    },

    phase_classification: phase,
    barriers_analysis:    barriers,

    product_recommendation: {
      primary_offer: { ...product, fit_score },
      financial_fit: { has_budget, budget_gap, estimated_ltv },
      upsell_path,
    },

    lead_qualification: {
      lead_temperature,
      lead_priority_score,
      ...enrichment,
      preferred_communication: "WhatsApp",
    },

    timeline_milestones: {
      next_milestone_action:   milestone.action,
      next_milestone_deadline: addMonths(today, milestone.months),
      recheck_recommended_at:  addMonths(today, milestone.recheck),
      scheduled_follow_up_1:   addDays(today, 7),
      scheduled_follow_up_2:   addDays(today, 30),
      scheduled_follow_up_3:   addDays(today, 90),
      auto_nurture_sequence,
    },

    tracking: lead.tracking || {},

    report_metadata: {
      generated_at:   today.toISOString(),
      report_version: "2.1",
      prompt_version: "v2.1",
      ai_model_used:  "claude-sonnet-4-5",
    },

    // remover em produção
    _debug: {
      english:    `"${lead.englishLevel}" → "${input.english_level}" → ${score_english}pts`,
      experience: `"${lead.experience}" → "${input.experiencia}" → ${score_experience}pts`,
      area:       `"${lead.area}" → "${input.area}"`,
      investment: `"${lead.investmentRange}" → "${input.investment_range}"`,
      income:     `"${lead.incomeRange}" → "${input.income_range}"`,
      impediment: `"${lead.impediment}" → "${input.impediment}" → ${score_readiness}pts`,
      flags:      { isHighTicket, isMedTicket, isFree, isLowTicket },
      total:      `${readiness_score}/100 → Fase ${phase.phase_id} → ${product.recommended_product_tier}`,
      upsell_path,
    },
  }
}];

