parameters.jsCode:
// ============================================================
// NODE 1 — CALCULADORA DE SCORE (regras comerciais revisadas)
// Tipo: Code (JavaScript) no n8n
// Input: $json.body  ← formulário EUA Na Prática
// Versão: 2.4 — score-driven tier (financial capacity informs, not gates)
// ============================================================

// ── ADAPTADOR DE INPUT ──────────────────────────────────────
// Mapeia os campos do formulário para o formato esperado pela engine

const body = $json.body;

const lead = {
  fullName:           body.lead.fullName          || "",
  email:              body.lead.email             || "",
  whatsapp:           body.lead.whatsapp          || "",
  currentRole:        body.lead.currentRole       || "",
  area:               body.lead.area              || "",
  worksInternational: body.lead.worksInternational|| "false",
  experience:         body.lead.experience        || "",
  englishLevel:       body.lead.englishLevel      || "",
  goal:               body.lead.goal              || "",
  visaStatus:         body.lead.visaStatus        || "",
  timeline:           body.lead.timeline          || "",
  familyStatus:       body.lead.familyStatus      || "",
  incomeRange:        body.lead.incomeRange       || "",
  investmentRange:    body.lead.investmentRange   || "",
  impediment:         body.lead.impediment        || "",
  mainConcern:        body.lead.mainConcern       || "",
  tracking: {
    submitted_at:            body.lead.tracking?.submitted_at            || "",
    completion_time_seconds: body.lead.tracking?.completion_time_seconds || "",
    device:                  body.lead.tracking?.device                  || "",
    consentimento_marketing: body.lead.tracking?.consentimento_marketing || "",
    utm_source:              body.lead.tracking?.utm_source              || "",
    utm_medium:              body.lead.tracking?.utm_medium              || "",
    utm_campaign:            body.lead.tracking?.utm_campaign            || "",
    utm_content:             body.lead.tracking?.utm_content             || "",
    utm_term:                body.lead.tracking?.utm_term                || "",
    fbclid:                  body.lead.tracking?.fbclid                  || "",
    gclid:                   body.lead.tracking?.gclid                   || "",
  },
};

// ── HELPER: strip acentos para normalização robusta ─────────

function strip(val = "") {
  return val.toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

// ── NORMALIZAÇÃO ────────────────────────────────────────────

function normalizeEnglish(val = "") {
  const v = strip(val);
  if (v.includes("fluente") || v.includes("nativo") || v.includes("native"))           return "Fluente";
  if (v.includes("avancado") || v.includes("advanced"))                                return "Avançado";
  if (v.includes("intermediario") || v.includes("intermediate"))                       return "Intermediário";
  return "Básico";
}

function normalizeExperience(val = "") {
  const v = strip(val).replace(/\s/g, "");
  if (v.includes("+10") || v.includes("10+") || v.includes("maisde10") || v.includes("acimade10")) return "+10 anos";
  if (v.includes("5-10") || v.includes("5a10") || v.includes("5e10") || (v.includes("5") && v.includes("10"))) return "5-10 anos";
  if (v.includes("2-5")  || v.includes("2a5")  || v.includes("2e5")  || (v.includes("2") && v.includes("5")))  return "2-5 anos";
  return "Menos de 2 anos";
}

function normalizeArea(val = "") {
  const v = strip(val);
  if (v.includes("sap") || v.includes("erp"))                                                                return "SAP/ERP";
  if (v.includes("tecnologia") || v.includes(" ti") || v.includes("/ti") || v.includes(" it") || v.includes("/it")) return "Tecnologia/IT";
  if (v.includes("gestao") || v.includes("business") || v.includes("negocio") || v.includes("administracao")) return "Gestão/Business";
  if (v.includes("engenharia") || v.includes("engineering"))                                                 return "Engenharia";
  if (v.includes("marketing") || v.includes("comunicacao"))                                                 return "Marketing/Comunicação";
  if (v.includes("saude") || v.includes("health"))                                                          return "Saúde";
  if (v.includes("estudante") || v.includes("student"))                                                     return "Estudante";
  return "Outros";
}

function normalizeObjective(val = "") {
  const v = strip(val);
  if (v.includes("green card") || v.includes("imigrar") || v.includes("imigracao"))    return "Imigrar/Green Card trabalhando na minha área";
  if (v.includes("remoto") || v.includes("dolar"))                                     return "Emprego remoto em dólar";
  if (v.includes("estudar") || v.includes("estudo") || v.includes("faculdade"))        return "Estudar nos EUA como porta de entrada";
  return "Ainda não tenho clareza, quero entender minhas opções";
}

function normalizeVisa(val = "") {
  const v = strip(val);
  if (v.includes("green card") || (v.includes("trabalho") && (v.includes("aprovado") || v.includes("tenho")))) return "Já tenho visto de trabalho ou Green Card aprovado";
  if (v.includes("andamento") || v.includes("em processo") || v.includes("em curso"))  return "Processo de visto/imigração em andamento";
  if (v.includes("turista") || v.includes("tourist") || v.includes("b1") || v.includes("b2")) return "Tenho/tive apenas visto de turista";
  return "Ainda não iniciei nada";
}

function normalizeTimeline(val = "") {
  const v = strip(val);
  if (v.includes("movimento") || (v.includes("3") && v.includes("proximo")))           return "Já estou em movimento / próximos 3 meses";
  if (v.includes("3") && v.includes("6"))                                               return "Entre 3 e 6 meses";
  if (v.includes("6") && v.includes("12"))                                              return "Entre 6 e 12 meses";
  return "Ainda não tenho prazo definido";
}

function normalizeFamilyStatus(val = "") {
  const v = strip(val);
  if (v.includes("filho"))                                                               return "Com família e filhos";
  if (v.includes("conjuge") || v.includes("companheiro") || v.includes("casado"))      return "Com cônjuge/companheiro(a)";
  if (v.includes("sozinho") || v.includes("sozinha") || v.includes("solteiro"))        return "Sozinho(a)";
  return "Ainda não pensei sobre isso";
}

function normalizeIncome(val = "") {
  const v = strip(val).replace(/\s/g, "");
  if (v.includes("prefiro") || v.includes("naoresponder") || v === "")                 return "Prefiro não responder";
  if (v.includes("acimade20") || (v.includes("20") && v.includes("acima")))            return "Acima de R$ 20 mil";
  if (v.includes("10") && v.includes("20"))                                             return "De R$ 10 mil a R$ 20 mil";
  if (v.includes("5")  && v.includes("10"))                                             return "De R$ 5 mil a R$ 10 mil";
  if (v.includes("ate5") || (v.includes("5") && v.includes("ate")))                    return "Até R$ 5 mil";
  return "Prefiro não responder";
}

function normalizeInvestment(val = "") {
  const v = strip(val).replace(/\s/g, "");
  if (v.includes("naose") || v.includes("naosei") || v.includes("organizar"))          return "Ainda não sei/preciso me organizar primeiro";
  if (v.includes("acimade5") || (v.includes("5") && v.includes("acima")))              return "Acima de R$ 5 mil";
  if (v.includes("2000") && v.includes("5000"))                                        return "De R$ 3 mil a R$ 5 mil";
  if (v.includes("500") && (v.includes("2000") || v.includes("2.000")))                return "De R$ 1.500 a R$ 3.000";
  if (v.includes("ate500") || (v.includes("500") && v.includes("ate")))                return "Até R$ 1.500";
  return "Ainda não sei/preciso me organizar primeiro";
}

function normalizeImpediment(val = "") {
  const v = strip(val);
  if (v.includes("pronto") || v.includes("nenhum"))                                    return "Nenhum, pois estou pronto(a)";
  if (v.includes("financeiro") || v.includes("dinheiro") || v.includes("custo"))      return "Financeiro";
  if (v.includes("tempo") || v.includes("rotina") || v.includes("agenda"))            return "Tempo ou rotina";
  if (v.includes("ingles") || v.includes("idioma"))                                   return "Inglês";
  if (v.includes("medo") || v.includes("decisao") || v.includes("errada"))            return "Medo de tomar uma decisão errada";
  if (v.includes("familia") || v.includes("conjuge") || v.includes("apoio"))          return "Falta de apoio do cônjuge ou família";
  return "Outro";
}

function normalizeWorksInternational(val = "") {
  const v = strip(val);
  return (v === "sim" || v === "yes" || v === "s" || v === "true" || v === "1") ? "Sim" : "Não";
}

// ── DADOS NORMALIZADOS ──────────────────────────────────────

const input = {
  name:                   lead.fullName,
  email:                  lead.email,
  phone:                  lead.whatsapp,
  area:                   normalizeArea(lead.area),
  raw_area:               lead.area,
  atuacao:                lead.currentRole,
  current_role:           lead.currentRole,
  trabalha_internacional: normalizeWorksInternational(lead.worksInternational),
  experiencia:            normalizeExperience(lead.experience),
  english_level:          normalizeEnglish(lead.englishLevel),
  raw_english_level:      lead.englishLevel,
  objetivo:               normalizeObjective(lead.goal),
  visa_status:            normalizeVisa(lead.visaStatus),
  timeline:               normalizeTimeline(lead.timeline),
  family_status:          normalizeFamilyStatus(lead.familyStatus),
  income_range:           normalizeIncome(lead.incomeRange),
  investment_range:       normalizeInvestment(lead.investmentRange),
  impediment:             normalizeImpediment(lead.impediment),
  main_concern:           lead.mainConcern,
};

// ── SCORE ───────────────────────────────────────────────────

const score_english            = { "Básico": 0, "Intermediário": 12, "Avançado": 20, "Fluente": 25 }[input.english_level] ?? 0;
const score_experience         = { "Menos de 2 anos": 5, "2-5 anos": 12, "5-10 anos": 17, "+10 anos": 20 }[input.experiencia] ?? 0;
const score_international_work = input.trabalha_internacional === "Sim" ? 15 : 5;
const score_timeline           = { "Já estou em movimento / próximos 3 meses": 10, "Entre 3 e 6 meses": 8, "Entre 6 e 12 meses": 5, "Ainda não tenho prazo definido": 2 }[input.timeline] ?? 0;
const score_objective          = { "Imigrar/Green Card trabalhando na minha área": 10, "Emprego remoto em dólar": 8, "Estudar nos EUA como porta de entrada": 6, "Ainda não tenho clareza, quero entender minhas opções": 0 }[input.objetivo] ?? 0;
const score_visa               = { "Já tenho visto de trabalho ou Green Card aprovado": 10, "Processo de visto/imigração em andamento": 7, "Tenho/tive apenas visto de turista": 3, "Ainda não iniciei nada": 0 }[input.visa_status] ?? 0;
const score_readiness          = { "Nenhum, pois estou pronto(a)": 10, "Tempo ou rotina": 6, "Medo de tomar uma decisão errada": 4, "Financeiro": 3, "Inglês": 2, "Falta de apoio do cônjuge ou família": 1, "Outro": 3 }[input.impediment] ?? 3;
const score_area_bonus         = 0;

const readiness_score = Math.min(
  score_english + score_experience + score_international_work +
  score_timeline + score_objective + score_visa + score_readiness + score_area_bonus,
  100
);

// ── FASE ────────────────────────────────────────────────────

let phase;
if      (readiness_score <= 35) phase = { phase_id: 0, phase_name: " Realidade & Direção",      phase_emoji: "❌", phase_color: "#DC2626", rota_letter: "Pré-R", urgency_level: "BAIXA",   can_apply_jobs: false, estimated_preparation_months: 24 };
else if (readiness_score <= 60) phase = { phase_id: 1, phase_name: "Organização", phase_emoji: "🟡", phase_color: "#F59E0B", rota_letter: "R-O",   urgency_level: "MÉDIA",   can_apply_jobs: false, estimated_preparation_months: 15 };
else if (readiness_score <= 85) phase = { phase_id: 2, phase_name: "Tração",           phase_emoji: "🟢", phase_color: "#10B981", rota_letter: "O-T",   urgency_level: "ALTA",    can_apply_jobs: true,  estimated_preparation_months: 9  };
else                            phase = { phase_id: 3, phase_name: "Aceleração",             phase_emoji: "🚀", phase_color: "#8B5CF6", rota_letter: "T-A",   urgency_level: "CRÍTICA", can_apply_jobs: true,  estimated_preparation_months: 3  };

// ── BARREIRAS ───────────────────────────────────────────────

const barriers = {
  has_english_barrier:    ["Básico", "Intermediário"].includes(input.english_level),
  has_experience_barrier: ["Menos de 2 anos", "2-5 anos"].includes(input.experiencia),
  has_financial_barrier:  input.income_range === "Até R$ 5 mil" || input.impediment === "Financeiro",
  has_family_barrier:     input.family_status === "Com família e filhos" || input.impediment === "Falta de apoio do cônjuge ou família",
  has_visa_barrier:       input.visa_status === "Ainda não iniciei nada",
  has_time_barrier:       input.impediment === "Tempo ou rotina",
  has_clarity_barrier:    input.objetivo === "Ainda não tenho clareza, quero entender minhas opções",
};

// ── TIER CLASSIFICATION (v2.4 — score-driven) ───────────────
// Score is the PRIMARY driver of tier. Financial capacity is passed as
// context to the LLM via financial_fit so it can address constraints
// in the recommendation description, but does NOT gate the tier.
//
// Thresholds aligned with phase_classification boundaries:
//   0-30  → FREE         (phase 0: Realidade & Direção)
//   31-50 → LOW_TICKET   (phase 0-1: building foundation)
//   51-70 → MED_TICKET   (phase 1-2: Organização/Tração)
//   71+   → HIGH_TICKET  (phase 2-3: Tração/Aceleração)

let recommended_product_tier;
if (readiness_score >= 71) {
  recommended_product_tier = 'HIGH_TICKET';
} else if (readiness_score >= 51) {
  recommended_product_tier = 'MED_TICKET';
} else if (readiness_score >= 31) {
  recommended_product_tier = 'LOW_TICKET';
} else {
  recommended_product_tier = 'FREE';
}

// Convenience flags (derived from tier, used by downstream logic)
const isHighTicket = recommended_product_tier === 'HIGH_TICKET';
const isMedTicket  = recommended_product_tier === 'MED_TICKET';
const isLowTicket  = recommended_product_tier === 'LOW_TICKET';
const isFree       = recommended_product_tier === 'FREE';

// ── FINANCIAL FIT (data-driven, independent of tier) ─────────
// has_budget reflects ACTUAL financial capacity, not tier assignment.
// A lead can be MED_TICKET (high score) but has_budget=false (no money yet).
// The LLM uses this to frame the recommendation appropriately.

const has_budget =
  !["Até R$ 1.500", "Ainda não sei/preciso me organizar primeiro"].includes(input.investment_range);

const budget_gap =
  !has_budget                    ? "Sem orçamento no momento" :
  input.impediment === "Financeiro" ? "Tem budget mas precisa superar objeção financeira" :
  ["De R$ 3 mil a R$ 5 mil", "Acima de R$ 5 mil"].includes(input.investment_range)
                                 ? "Compatível" :
                                   "Acessível com parcelamento";

// ── FIT SCORE & LTV ─────────────────────────────────────────
// fit_score combines readiness (tier) with financial capacity.
// A high-score lead without budget has decent fit but penalized.

let fit_score, estimated_ltv;

if (isHighTicket) {
  fit_score     = has_budget
    ? Math.min(85 + Math.round((readiness_score - 71) / 2), 100)
    : Math.min(65 + Math.round((readiness_score - 71) / 2), 80);
  estimated_ltv = has_budget ? 10000 : 3000;
} else if (isMedTicket) {
  const financial_penalty = !has_budget ? 10 : (input.impediment === "Financeiro" ? 8 : 0);
  fit_score     = Math.min(70 + Math.round((readiness_score - 51) / 2) - financial_penalty, 85);
  estimated_ltv = has_budget ? 2500 : 500;
} else if (isLowTicket) {
  fit_score     = Math.min(50 + Math.round((readiness_score - 31) / 3), 70);
  estimated_ltv = has_budget ? 700 : 200;
} else {
  fit_score     = Math.min(30 + Math.round(readiness_score / 2), 45);
  estimated_ltv = 0;
}

// ── TEMPERATURA & PRIORITY ──────────────────────────────────

const lead_temperature =
  readiness_score >= 80 && has_budget ? "SUPER_QUENTE" :
  readiness_score >= 65 && has_budget ? "QUENTE" :
  readiness_score >= 40               ? "MORNO" :
                                        "FRIO";

const urgency_bonus       = phase.urgency_level === "CRÍTICA" ? 10 : phase.urgency_level === "ALTA" ? 5 : 0;
const lead_priority_score = Math.round(
  (readiness_score * 0.4) + (fit_score * 0.3) + (has_budget ? 20 : 0) + urgency_bonus
);

// ── ENRICHMENT ──────────────────────────────────────────────

const enrichment = {
  is_tech_professional: input.area === "Tecnologia/IT",
  is_senior_level:      ["5-10 anos", "+10 anos"].includes(input.experiencia),
  works_remotely:       input.trabalha_internacional === "Sim",
  has_family:           input.family_status === "Com família e filhos",
  is_high_income:       ["De R$ 10 mil a R$ 20 mil", "Acima de R$ 20 mil"].includes(input.income_range),
};

// ── UPSELL PATH (CRM-only, not sent to AI) ──────────────────

const upsell_path =
  isHighTicket ? "Manter em HIGH → Alumni/Indicações" :
  isMedTicket && !has_budget ? "MED sem budget → nurture financeiro → oferta MED após 60-90 dias" :
  isMedTicket  ? "MED → oferta HIGH após 60-90 dias se score evoluir" :
  isLowTicket  ? "LOW → oferta MED após completar módulos iniciais" :
                 "FREE → oferta LOW após 30-60 dias quando engajar";

// ── DATAS ───────────────────────────────────────────────────

const today     = new Date();
const addDays   = (d, n) => new Date(d.getTime() + n * 86400000).toISOString().split("T")[0];
const addMonths = (d, n) => { const r = new Date(d); r.setMonth(r.getMonth() + n); return r.toISOString().split("T")[0]; };

const milestone = {
  0: { action: "Atingir inglês B2 e ganhar 2+ anos de experiência internacional",   months: 24, recheck: 6 },
  1: { action: "Elevar inglês para C1 e otimizar LinkedIn para o mercado americano", months: 15, recheck: 4 },
  2: { action: "Aplicar para 20+ vagas estratégicas e conseguir 3+ entrevistas",    months: 9,  recheck: 2 },
  3: { action: "Negociar ofertas simultaneamente e iniciar processo de visto",       months: 3,  recheck: 1 },
}[phase.phase_id];

// ── NURTURE SEQUENCE ────────────────────────────────────────

let auto_nurture_sequence;
if (isFree && barriers.has_financial_barrier) {
  auto_nurture_sequence = "Free_FinancialBarrier_Nurture";
} else if (isFree) {
  auto_nurture_sequence = "Free_Content_Engagement";
} else if (phase.phase_id === 0 && barriers.has_english_barrier) {
  auto_nurture_sequence = "Fase0_Ingles_Basico";
} else if (phase.phase_id === 0 && barriers.has_experience_barrier) {
  auto_nurture_sequence = "Fase0_Sem_Experiencia";
} else if (isMedTicket && !has_budget) {
  auto_nurture_sequence = "MedTicket_NoBudget_Nurture";
} else if (isMedTicket && barriers.has_financial_barrier) {
  auto_nurture_sequence = "Fase1_Med_Ticket_FinancialObjection";
} else if (isMedTicket) {
  auto_nurture_sequence = "Fase1_Med_Ticket_Nurture";
} else if (isLowTicket && phase.phase_id === 1) {
  auto_nurture_sequence = "Fase1_Low_Ticket_Education";
} else if (phase.phase_id === 2) {
  auto_nurture_sequence = "Fase2_Traction_Active";
} else {
  auto_nurture_sequence = "Fase3_Acceleration_VIP";
}

// ── RETORNO ─────────────────────────────────────────────────
// NOTE: product_recommendation is NO LONGER included here.
// The recommend-product edge function handles product selection dynamically
// by querying hub_services and calling LLM — triggered automatically via
// Postgres trigger when formatted_report is saved.

return [{
  json: {
    user_data: {
      name:                   input.name,
      email:                  input.email,
      phone:                  input.phone,
      area:                   input.area,
      raw_area:               input.raw_area,
      atuacao:                input.atuacao,
      current_role:           input.current_role,
      trabalha_internacional: input.trabalha_internacional,
      experiencia:            input.experiencia,
      english_level:          input.english_level,
      raw_english_level:      input.raw_english_level,
      objetivo:               input.objetivo,
      visa_status:            input.visa_status,
      timeline:               input.timeline,
      family_status:          input.family_status,
      income_range:           input.income_range,
      investment_range:       input.investment_range,
      impediment:             input.impediment,
      main_concern:           input.main_concern,
    },

    scoring: {
      readiness_score,
      readiness_percentual: Math.round(readiness_score),
      max_score: 100,
      score_breakdown: {
        score_english,
        score_experience,
        score_international_work,
        score_timeline,
        score_objective,
        score_visa,
        score_readiness,
        score_area_bonus,
      },
    },

    phase_classification: phase,
    barriers_analysis:    barriers,

    lead_qualification: {
      lead_temperature,
      lead_priority_score,
      recommended_product_tier,
      ...enrichment,
      preferred_communication: "WhatsApp",
      financial_fit: { has_budget, budget_gap, estimated_ltv },
    },

    timeline_milestones: {
      next_milestone_action:   milestone.action,
      next_milestone_deadline: addMonths(today, milestone.months),
      recheck_recommended_at:  addMonths(today, milestone.recheck),
      scheduled_follow_up_1:   addDays(today, 7),
      scheduled_follow_up_2:   addDays(today, 30),
      scheduled_follow_up_3:   addDays(today, 90),
      auto_nurture_sequence,
    },

    tracking: lead.tracking,

    report_metadata: {
      generated_at:   today.toISOString(),
      report_version: "2.4",
      prompt_version: "v2.4",
      ai_model_used:  "claude-sonnet-4-5",
    },

    _debug: {
      english:    `"${lead.englishLevel}" → "${input.english_level}" → ${score_english}pts`,
      experience: `"${lead.experience}" → "${input.experiencia}" → ${score_experience}pts`,
      area:       `"${lead.area}" → "${input.area}"`,
      investment: `"${lead.investmentRange}" → "${input.investment_range}"`,
      income:     `"${lead.incomeRange}" → "${input.income_range}"`,
      impediment: `"${lead.impediment}" → "${input.impediment}" → ${score_readiness}pts`,
      current_role: `"${lead.currentRole}"`,
      works_intl: `"${lead.worksInternational}" → "${input.trabalha_internacional}"`,
      tier_logic: `score=${readiness_score} → ${recommended_product_tier} | has_budget=${has_budget}`,
      total:      `${readiness_score}/100 → Fase ${phase.phase_id} → ${recommended_product_tier}`,
      upsell_path,
    },
  }
}];

// ============================================================
// NODE 3 — PREPARAÇÃO DE DADOS PARA SUPABASE (SMART PARSE)
// Input: output do Claude (AI Agent node)
// Compatível com: JSON Input v2.3 (produto decoupled)
// ============================================================

const rootInput = $input.first().json;

// ── PARSE INTELIGENTE ───────────────────────────────────────
// Esta seção procura o JSON correto, não importa onde o n8n o escondeu

let aiReport = null;

// Função auxiliar para limpar Markdown (```json ... ```) e parsear
const parseString = (str) => {
    if (!str || typeof str !== 'string') return null;
    try {
        const cleaned = str
            .replace(/^```json\s*/, '') // Remove inicio ```json
            .replace(/^```\s*/, '')     // Remove inicio ```
            .replace(/\s*```$/, '')     // Remove fim ```
            .trim();
        return JSON.parse(cleaned);
    } catch (e) {
        return null;
    }
};

// 1. Tenta pegar direto da raiz (se o node anterior já entregou o objeto pronto)
if (rootInput.user_data && rootInput.scoring) {
    aiReport = rootInput;
} 
// 2. Tenta pegar de dentro de 'output' (padrão AI Agent do n8n)
else if (rootInput.output) {
    if (typeof rootInput.output === 'object') {
        aiReport = rootInput.output;
    } else {
        aiReport = parseString(rootInput.output);
    }
}
// 3. Tenta pegar de dentro de 'text' ou 'message.content' (outros padrões)
else if (rootInput.text) {
    aiReport = parseString(rootInput.text);
}

// Se depois de tudo isso ainda for null ou não tiver user_data, lança erro detalhado
if (!aiReport || !aiReport.user_data) {
    throw new Error(
        `Não foi possível encontrar o JSON válido. \n` +
        `Input recebido: ${JSON.stringify(rootInput).substring(0, 200)}...`
    );
}

// ── VALIDAÇÃO ───────────────────────────────────────────────

const requiredFields = [
    'user_data',
    'scoring',
    'phase_classification',
    'barriers_analysis',
    // product_recommendation REMOVED — decoupled to recommend-product edge function
    'lead_qualification',
    'timeline_milestones'
];

const missingFields = requiredFields.filter(field => !aiReport[field]);
if (missingFields.length > 0) {
    throw new Error(`JSON da IA incompleto. Campos faltando: ${missingFields.join(', ')}`);
}

// ── HELPERS ─────────────────────────────────────────────────

const toBool = (val) => {
    if (typeof val === 'boolean') return val;
    if (typeof val === 'string') {
        const v = val.toLowerCase().trim();
        return ['sim', 'true', '1', 'yes', 'não', 'nao', 'false', '0'].includes(v) 
            ? (['sim', 'true', '1', 'yes'].includes(v)) 
            : false;
    }
    if (typeof val === 'number') return val !== 0;
    return false;
};

// Permite string vazia "" mas bloqueia null/undefined
const required = (value, fieldName) => {
    if (value === undefined || value === null) {
        throw new Error(`Campo obrigatório ausente: ${fieldName}`);
    }
    return value;
};

const toInt = (val) => {
    if (val === null || val === undefined || val === '') return null;
    if (typeof val === 'number') return Math.round(val);
    const n = parseInt(String(val).replace(/[^0-9.-]/g, ''), 10);
    return isNaN(n) ? null : n;
};

const toNumeric = (val) => {
    if (val === null || val === undefined || val === '') return null;
    if (typeof val === 'number') return val;
    const n = parseFloat(String(val).replace(/[^0-9.-]/g, ''));
    return isNaN(n) ? null : n;
};

// ── EXTRAÇÃO ────────────────────────────────────────────────

const user = aiReport.user_data || {};
const scoring = aiReport.scoring || {};
const phase = aiReport.phase_classification || {};
const barriers = aiReport.barriers_analysis || {};
const lead = aiReport.lead_qualification || {};
const timeline = aiReport.timeline_milestones || {};
const financialFit = lead.financial_fit || {};

// ── PREPARAÇÃO JSONB ────────────────────────────────────────
const {
    _debug,
    tracking,
    database_fields, 
    report_metadata,
    ...reportClean
} = aiReport;

const reportContent = phase.short_diagnosis || 
    `${phase.phase_emoji} ${phase.phase_name} — Score: ${scoring.readiness_score}/100`;

// ── RECORD FINAL ────────────────────────────────────────────

const record = {

    // ── DADOS DO FORMULÁRIO ──────────────────────────────────
    email: required(user.email, 'user_data.email'),
    name: required(user.name, 'user_data.name'),
    phone: user.phone || '',
    area: required(user.area, 'user_data.area'),
    atuacao: user.atuacao || '',
    trabalha_internacional: toBool(user.trabalha_internacional),
    experiencia: required(user.experiencia, 'user_data.experiencia'),
    english_level: required(user.english_level, 'user_data.english_level'),
    objetivo: required(user.objetivo, 'user_data.objetivo'),
    visa_status: user.visa_status || '',
    timeline: user.timeline || '',
    family_status: user.family_status || '',
    income_range: user.income_range || '',
    investment_range: user.investment_range || '',
    impediment: user.impediment || '',
    impediment_other: null,
    main_concern: user.main_concern || null,

    // ── RELATÓRIO ────────────────────────────────────────────
    report_content: reportContent,
    formatted_report: reportClean,
    formatted_at: new Date().toISOString(),

    // ── SCORING & FASE ───────────────────────────────────────
    readiness_score: toInt(required(scoring.readiness_score, 'scoring.readiness_score')),
    readiness_percentual: toNumeric(required(scoring.readiness_percentual, 'scoring.readiness_percentual')),
    phase_id: toInt(required(phase.phase_id, 'phase_classification.phase_id')),
    phase_name: required(phase.phase_name, 'phase_classification.phase_name'),
    phase_emoji: required(phase.phase_emoji, 'phase_classification.phase_emoji'),
    rota_letter: required(phase.rota_letter, 'phase_classification.rota_letter'),
    urgency_level: required(phase.urgency_level, 'phase_classification.urgency_level'),
    can_apply_jobs: toBool(required(phase.can_apply_jobs, 'phase_classification.can_apply_jobs')),
    estimated_preparation_months: toInt(required(phase.estimated_preparation_months, 'phase_classification.estimated_preparation_months')),

    // ── SCORE BREAKDOWN ──────────────────────────────────────
    score_english: toInt(scoring.score_breakdown?.score_english),
    score_experience: toInt(scoring.score_breakdown?.score_experience),
    score_international_work: toInt(scoring.score_breakdown?.score_international_work),
    score_timeline: toInt(scoring.score_breakdown?.score_timeline),
    score_objective: toInt(scoring.score_breakdown?.score_objective),
    score_visa: toInt(scoring.score_breakdown?.score_visa),
    score_readiness: toInt(scoring.score_breakdown?.score_readiness),
    score_area_bonus: toInt(scoring.score_breakdown?.score_area_bonus || 0),

    // ── PRODUTO (decoupled — recommend-product edge function populates these) ──
    recommended_product_tier: required(lead.recommended_product_tier, 'lead_qualification.recommended_product_tier'),
    recommended_product_name: null,   // edge function: recommend-product
    recommended_product_price: null,  // edge function: recommend-product
    recommended_product_url: null,    // edge function: recommend-product
    fit_score: null,                  // edge function: recommend-product

    // ── SECONDARY PRODUCT (removed — decoupled) ──────────────
    secondary_product_tier: null,
    secondary_product_name: null,
    secondary_fit_score: null,

    // ── FINANCIAL FIT (now in lead_qualification) ────────────
    has_budget: toBool(financialFit.has_budget),
    budget_gap: financialFit.budget_gap || '',
    estimated_ltv: toNumeric(financialFit.estimated_ltv),

    // ── BARREIRAS ────────────────────────────────────────────
    has_english_barrier: toBool(barriers.has_english_barrier),
    has_experience_barrier: toBool(barriers.has_experience_barrier),
    has_financial_barrier: toBool(barriers.has_financial_barrier),
    has_family_barrier: toBool(barriers.has_family_barrier),
    has_visa_barrier: toBool(barriers.has_visa_barrier),
    has_time_barrier: toBool(barriers.has_time_barrier),
    has_clarity_barrier: toBool(barriers.has_clarity_barrier),
    critical_blockers: barriers.critical_blockers || [],
    recommended_first_action: required(barriers.recommended_first_action, 'barriers.first_action'),

    // ── LEAD QUALIFICATION ───────────────────────────────────
    is_tech_professional: toBool(lead.is_tech_professional),
    is_senior_level: toBool(lead.is_senior_level),
    works_remotely: toBool(lead.works_remotely),
    has_family: toBool(lead.has_family),
    is_high_income: toBool(lead.is_high_income),
    lead_temperature: required(lead.lead_temperature, 'lead.temperature'),
    lead_priority_score: toInt(required(lead.lead_priority_score, 'lead.priority')),
    best_contact_time: lead.best_contact_time || '',
    preferred_communication: lead.preferred_communication || '',

    // ── TIMELINE & MILESTONES ────────────────────────────────
    next_milestone_action: required(timeline.next_milestone_action, 'timeline.next_action'),
    next_milestone_deadline: required(timeline.next_milestone_deadline, 'timeline.deadline'),
    recheck_recommended_at: required(timeline.recheck_recommended_at, 'timeline.recheck'),
    scheduled_follow_up_1: timeline.scheduled_follow_up_1 || null,
    scheduled_follow_up_2: timeline.scheduled_follow_up_2 || null,
    scheduled_follow_up_3: timeline.scheduled_follow_up_3 || null,
    auto_nurture_sequence: timeline.auto_nurture_sequence || 'default',

    // ── STATUS ───────────────────────────────────────────────
    processing_status: 'completed',
    processing_error: null,
    access_count: 0,
};

// ── RETORNO ────────────────────────────────────────────────
console.log(`✅ Processado com sucesso: ${record.email} (Score: ${record.readiness_score})`);
return { json: record };

